parts.text:
[
  {
    "statement": "Both short and long flexible habitats created on subtidal artificial structures in Australia show mixed effects on fish and invertebrate populations.",
    "citations": []
  },
  {
    "statement": "Long flexible habitats supported macroalgae species that were absent from structure surfaces without flexible habitats.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Long flexible habitats supported non-mobile invertebrate species that were absent from structure surfaces without flexible habitats.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Long flexible habitats had mixed effects on fish species richness depending on fish presence when the habitats were created.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Long flexible habitats supported higher combined macroalgae and invertebrate biomass compared to surfaces without habitats.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "The increased invertebrate biomass on long flexible habitats was mostly composed of mussels.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Short flexible habitats showed mixed effects on invertebrate community composition, with effects depending on habitat density, length, and site location.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "Short flexible habitats did not increase invertebrate species richness on structure surfaces.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "Both short and long flexible habitat types showed mixed effects on invertebrate and fish abundance.",
    "citations": []
  },
  {
    "statement": "The effects of flexible habitats on invertebrate and fish abundance depended on various factors including species group, survey timing, and habitat characteristics.",
    "citations": []
  }
]

[
  {
    "statement": "There is currently no evidence base for the effectiveness of creating large protrusions (>50 mm) or large ridges/ledges (>50 mm) on subtidal artificial structures.",
    "citations": []
  },
  {
    "statement": "No studies were found that directly evaluated the creation of large protrusions or ridges on subtidal artificial structures during comprehensive literature searches.",
    "citations": []
  },
  {
    "statement": "For small protrusions (1-50 mm), one controlled study in Japan found mixed effects on macroalgal abundance depending on the species.",
    "citations": []
  },
  {
    "statement": "For natural rocky reef topography, one replicated, randomized, controlled study in Italy found that this intervention did not increase the abundance of juvenile canopy macroalgae regardless of topography depth.",
    "citations": []
  },
  {
    "statement": "The complete lack of studies examining large protrusions and ridges means there is no evidence to indicate whether creating large protrusions and ridges has any desirable or harmful effects on biodiversity.",
    "citations": []
  }
]

[
  {
    "statement": "Ten studies examined transplanting organisms onto intertidal artificial structures in estuaries.",
    "citations": []
  },
  {
    "statement": "Seven of the ten studies were conducted in southeast Australian estuaries.",
    "citations": []
  },
  {
    "statement": "Studies focused primarily on oyster transplantation and revealed mixed outcomes.",
    "citations": []
  },
  {
    "statement": "Transplanted oysters supported macroalgae, mobile invertebrate, non-mobile invertebrate, and fish species.",
    "citations": []
  },
  {
    "statement": "The species supported by transplanted oysters were absent from structures without oysters.",
    "citations": []
  },
  {
    "statement": "Transplanting oysters had mixed effects on the combined species richness of macroalgae and invertebrates.",
    "citations": []
  },
  {
    "statement": "The effects of transplanting oysters on species richness depended on the site and the presence of grooves and small ridges on surfaces.",
    "citations": []
  },
  {
    "statement": "Oyster transplantation increased the species richness of mobile invertebrates.",
    "citations": []
  },
  {
    "statement": "Oyster transplantation did not consistently increase the species richness or abundance of fish.",
    "citations": []
  },
  {
    "statement": "The survival of transplanted organisms varied depending on the species, site conditions, and structural features.",
    "citations": []
  },
  {
    "statement": "The survival of transplanted oysters was higher in grooves compared with ridges.",
    "citations": []
  },
  {
    "statement": "The survival rates of transplanted oysters also varied by site.",
    "citations": []
  },
  {
    "statement": "Studies found that transplanting oysters did not increase the overall combined abundance of macroalgae and invertebrates.",
    "citations": []
  },
  {
    "statement": "The effects of transplanting oysters on abundance varied with surface features like grooves and ridges.",
    "citations": []
  },
  {
    "statement": "Transplanting oysters and/or coralline algae did not increase fish abundance.",
    "citations": []
  },
  {
    "statement": "Transplanting oysters and/or coralline algae did not increase the time fish spent interacting with structure surfaces.",
    "citations": []
  }
]

[
  {
    "statement": "The most effective habitat creation methods for increasing overall species richness and diversity on intertidal artificial structures have been identified from multiple studies.",
    "citations": []
  },
  {
    "statement": "Pit habitats are the most consistently effective method for increasing combined macroalgae and invertebrate species richness and/or diversity.",
    "citations": []
  },
  {
    "statement": "Studies on pit habitats were conducted across various locations in the UK and Singapore.",
    "citations": []
  },
  {
    "statement": "Pit habitats supported species that were absent from structure surfaces without pits.",
    "citations": []
  },
  {
    "statement": "Groove habitats showed mixed but generally positive results for increasing combined macroalgae and invertebrate species richness and/or diversity.",
    "citations": []
  },
  {
    "statement": "Grooves supported species absent from surfaces without grooves.",
    "citations": []
  },
  {
    "statement": "Rock pools demonstrated strong effectiveness, showing higher combined macroalgae, invertebrate and/or fish species diversity and/or richness compared to structure surfaces without pools.",
    "citations": []
  },
  {
    "statement": "Rock pools supported species that were absent from surfaces without pools.",
    "citations": []
  },
  {
    "statement": "Rock pools provided habitat for various taxa including macroalgae, invertebrates, and fishes.",
    "citations": []
  },
  {
    "statement": "Combined groove and ridge/ledge habitats showed positive results in increasing combined macroalgae and invertebrate species diversity and/or richness.",
    "citations": []
  },
  {
    "statement": "The results for combined groove and ridge/ledge habitats were mixed depending on factors such as size, arrangement, shore level, and site.",
    "citations": []
  },
  {
    "statement": "Hole habitats were effective in increasing combined macroalgae and invertebrate species diversity and/or richness.",
    "citations": []
  },
  {
    "statement": "Hole habitats supported species absent from surfaces without holes.",
    "citations": []
  },
  {
    "statement": "Short flexible habitats decreased species richness.",
    "citations": []
  },
  {
    "statement": "Small ridges or ledges used alone generally supported lower species richness than grooves.",
    "citations": []
  },
  {
    "statement": "Natural rocky reef topography showed limited effectiveness in increasing species richness.",
    "citations": []
  },
  {
    "statement": "Small swimthrough habitats showed limited effectiveness in increasing species richness.",
    "citations": []
  }
]

[
  {
    "statement": "In European marine environments, creating textured surfaces on intertidal artificial structures shows varied outcomes.",
    "citations": []
  },
  {
    "statement": "Textured surfaces of one millimeter or less on intertidal structures demonstrated mixed effects on species richness.",
    "citations": []
  },
  {
    "statement": "The effects of textured surfaces on species richness depend on the type of texture created and the specific site.",
    "citations": []
  },
  {
    "statement": "In studies from the Netherlands, textured surfaces did not significantly increase macroalgal abundance.",
    "citations": []
  },
  {
    "statement": "Invertebrate abundance showed variable responses to textured surfaces.",
    "citations": []
  },
  {
    "statement": "A UK study found that creating textured surfaces along with environmentally-sensitive material increased barnacle abundance regardless of texture type.",
    "citations": []
  },
  {
    "statement": "In a UK study, different textures on environmentally-sensitive material supported different abundances of barnacles.",
    "citations": []
  },
  {
    "statement": "The effectiveness of surface texturing appears to be context-dependent, varying by location and species group.",
    "citations": []
  },
  {
    "statement": "Some studies on surface texturing show no significant increase in overall species richness or abundance.",
    "citations": []
  },
  {
    "statement": "Natural rocky reef topography created on intertidal structures in UK sites showed mixed effects on invertebrate abundance.",
    "citations": []
  },
  {
    "statement": "Natural rocky reef topography created on intertidal structures in UK sites did not consistently increase species richness.",
    "citations": []
  },
  {
    "statement": "Groove habitats created alongside ridges and ledges demonstrated site-dependent effects on biodiversity.",
    "citations": []
  },
  {
    "statement": "The creation of groove habitats in some European locations showed increased species richness.",
    "citations": []
  },
  {
    "statement": "The creation of groove habitats in other European locations showed no significant changes in biodiversity.",
    "citations": []
  }
]

[
  {
    "statement": "Several actions can enhance fish communities on subtidal artificial structures.",
    "citations": []
  },
  {
    "statement": "Creating large swimthroughs (greater than 100 mm) on subtidal structures increased overall fish abundance and species richness.",
    "citations": []
  },
  {
    "statement": "Small swimthroughs (100 mm or less) supported higher juvenile fish species richness in some locations but not in others.",
    "citations": []
  },
  {
    "statement": "Managing or restricting harvesting on subtidal artificial structures was found to support different fish communities.",
    "citations": []
  },
  {
    "statement": "Higher fish species richness was found around subtidal artificial structures with harvesting restrictions.",
    "citations": []
  },
  {
    "statement": "Creating long flexible habitats (greater than 50 mm) on subtidal structures supported fish species that were absent from structures without flexible habitats.",
    "citations": []
  },
  {
    "statement": "Creating long flexible habitats on subtidal structures had mixed effects on fish abundance.",
    "citations": []
  },
  {
    "statement": "Creating groove habitats (1–50 mm) on subtidal structures altered fish community composition.",
    "citations": []
  },
  {
    "statement": "Groove habitats on subtidal structures supported fish species that were absent from structures without added habitat features.",
    "citations": []
  },
  {
    "statement": "Ceasing or altering maintenance activities, such as reducing cleaning frequency, can increase the abundance of certain fish species like seahorses on subtidal structures.",
    "citations": []
  },
  {
    "statement": "Other potential habitat modifications for fish enhancement include creating large protrusions (greater than 50 mm), large ridges or ledges (greater than 50 mm), small protrusions (1–50 mm), and natural rocky reef topography.",
    "citations": []
  },
  {
    "statement": "Limited direct evidence is available for the effects on fish communities from creating large protrusions, large ridges or ledges, small protrusions, and natural rocky reef topography.",
    "citations": []
  }
]

[
  {
    "statement": "Hole habitats and pit habitats on intertidal artificial structures both support biodiversity.",
    "citations": []
  },
  {
    "statement": "There are key differences in the effects of hole habitats and pit habitats on biodiversity.",
    "citations": []
  },
  {
    "statement": "Hole habitats have been studied less extensively compared to pit habitats.",
    "citations": [
      "5",
      "22"
    ]
  },
  {
    "statement": "Both hole habitats and pit habitats can support species that are absent from structure surfaces without added features.",
    "citations": []
  },
  {
    "statement": "Hole habitats support macroalgae and non-mobile invertebrate species.",
    "citations": []
  },
  {
    "statement": "Pit habitats support macroalgae, invertebrate, and fish species.",
    "citations": []
  },
  {
    "statement": "Hole habitats consistently increased the combined diversity and richness of macroalgae and invertebrate species.",
    "citations": [
      "3"
    ]
  },
  {
    "statement": "Pit habitats showed more variable results regarding their effects on species richness and diversity.",
    "citations": [
      "8",
      "12"
    ]
  },
  {
    "statement": "Some studies found that pit habitats increased species richness or diversity, while others found no effect or mixed effects depending on site conditions.",
    "citations": [
      "8",
      "12"
    ]
  },
  {
    "statement": "Hole habitats showed no significant increases in macroalgal abundance.",
    "citations": [
      "1"
    ]
  },
  {
    "statement": "Hole habitats had mixed effects on invertebrate abundance.",
    "citations": [
      "2"
    ]
  },
  {
    "statement": "Pit habitats demonstrated complex patterns regarding their effects on the abundance of organisms.",
    "citations": []
  },
  {
    "statement": "In some cases, pit habitats showed increased combined macroalgae and invertebrate abundance, but in other cases, they showed no effect or decreased abundance.",
    "citations": []
  },
  {
    "statement": "Fish abundance and richness were only measured for pit habitats.",
    "citations": []
  },
  {
    "statement": "Increases in fish abundance and richness were found when pits were combined with grooves.",
    "citations": [
      "1"
    ]
  },
  {
    "statement": "Both hole habitats and pit habitats were used by various organisms including sea slugs, urchins, and octopuses.",
    "citations": []
  },
  {
    "statement": "Pit habitats also supported periwinkles and macroalgae.",
    "citations": []
  },
  {
    "statement": "Pit habitats also provided feeding opportunities for fish.",
    "citations": []
  }
]

[
  {
    "statement": "Research on environmentally-sensitive materials on subtidal artificial structures in Israel, the UK, and Australia shows mixed outcomes.",
    "citations": []
  },
  {
    "statement": "In Israel, using ECOncreteTM instead of standard-concrete, along with creating texture and habitats, altered macroalgae and invertebrate community composition.",
    "citations": []
  },
  {
    "statement": "In Israel, using ECOncreteTM instead of standard-concrete, along with creating texture and habitats, increased species diversity.",
    "citations": []
  },
  {
    "statement": "The use of ECOncreteTM in Israel had mixed effects on fish abundance.",
    "citations": []
  },
  {
    "statement": "In the UK, using recycled-cement-concrete instead of standard-concrete altered native community composition.",
    "citations": []
  },
  {
    "statement": "In the UK, using recycled-cement-concrete instead of standard-concrete did not increase diatom or macroalgae species richness.",
    "citations": []
  },
  {
    "statement": "In the UK, shell-concrete applications increased bivalve abundance.",
    "citations": []
  },
  {
    "statement": "In Australia, using shell-concrete instead of standard-concrete altered community composition.",
    "citations": []
  },
  {
    "statement": "In Australia, using shell-concrete instead of standard-concrete did not increase macroalgal abundance.",
    "citations": []
  },
  {
    "statement": "The use of shell-concrete in Australia had mixed effects on mobile invertebrate abundance, with effects depending on species groups and sites.",
    "citations": []
  },
  {
    "statement": "Across Israel, the UK, and Australia, ECOncreteTM consistently increased species diversity and richness and sometimes abundance.",
    "citations": []
  },
  {
    "statement": "Quarried rock and recycled-cement-concrete showed more variable results across the locations of Israel, the UK, and Australia.",
    "citations": []
  },
  {
    "statement": "The results for quarried rock and recycled-cement-concrete often depended on specific sites and environmental conditions.",
    "citations": []
  }
]

[
  {
    "statement": "The evidence for managing human activities on intertidal artificial structures is limited.",
    "citations": []
  },
  {
    "statement": "Two studies examined managing or restricting the harvesting of species on intertidal artificial structures.",
    "citations": []
  },
  {
    "statement": "A study in Gibraltar and Spain found that restricting human access on intertidal artificial structures resulted in larger limpets with more balanced sex ratios compared to unrestricted structures.",
    "citations": []
  },
  {
    "statement": "The study in Gibraltar and Spain found that restricting human access did not increase limpet abundance on the surfaces of intertidal artificial structures.",
    "citations": []
  },
  {
    "statement": "A study in Italy reported that legally restricting human access on intertidal artificial structures did not prevent people from harvesting invertebrates and fishes on and around the structures.",
    "citations": []
  },
  {
    "statement": "No studies were found that evaluated the effects of ceasing or altering maintenance activities on intertidal artificial structures.",
    "citations": []
  },
  {
    "statement": "There is a complete lack of evidence for managing intertidal artificial structures by ceasing or altering maintenance activities.",
    "citations": []
  }
]

[
  {
    "statement": "The survival and growth of canopy algae transplanted onto subtidal artificial structures are influenced by several key factors.",
    "citations": []
  },
  {
    "statement": "Wave-exposure and surrounding habitat significantly affect the survival of transplanted canopy algae.",
    "citations": []
  },
  {
    "statement": "Some studies report complete transplant failure of canopy algae regardless of protective measures.",
    "citations": []
  },
  {
    "statement": "The presence of cages around canopy algae transplants is crucial.",
    "citations": []
  },
  {
    "statement": "Caged canopy algae transplants show increased cover and survival compared to uncaged ones.",
    "citations": []
  },
  {
    "statement": "The mesh size of cages does not always significantly impact the growth of canopy algae.",
    "citations": []
  },
  {
    "statement": "Surface orientation has mixed effects on transplanted canopy algae.",
    "citations": []
  },
  {
    "statement": "Surface orientation influences the growth of canopy algae in some studies.",
    "citations": []
  },
  {
    "statement": "Surface orientation does not affect the survival of canopy algae in other studies.",
    "citations": []
  },
  {
    "statement": "Protective caging consistently enhances both canopy algae cover and survival on subtidal artificial structures.",
    "citations": []
  }
]

[
  {
    "statement": "Pit habitats showed positive effects for species richness and diversity.",
    "citations": []
  },
  {
    "statement": "Pit habitats showed positive effects for overall abundance of species.",
    "citations": []
  },
  {
    "statement": "Pit habitats are effective for supporting macroalgae, invertebrate, and fish species.",
    "citations": []
  },
  {
    "statement": "Groove habitats were effective for increasing species richness and diversity.",
    "citations": []
  },
  {
    "statement": "Groove habitats were effective for increasing the overall abundance of species.",
    "citations": []
  },
  {
    "statement": "Creating grooves combined with small protrusions, ridges, or ledges showed the strongest consistent results for increased species richness and diversity.",
    "citations": []
  },
  {
    "statement": "Creating grooves combined with small protrusions, ridges, or ledges has shown positive effects worldwide.",
    "citations": []
  },
  {
    "statement": "Using environmentally-sensitive materials like ECOncrete™ showed promise for altering community composition.",
    "citations": []
  },
  {
    "statement": "Using environmentally-sensitive materials like ECOncrete™ showed promise for increasing species richness.",
    "citations": []
  },
  {
    "statement": "Transplanting or seeding organisms, particularly oysters, was effective for supporting new species.",
    "citations": []
  },
  {
    "statement": "Transplanting or seeding organisms showed mixed results for richness increases.",
    "citations": []
  },
  {
    "statement": "Habitat modifications on intertidal artificial structures consistently supported species that were absent from standard structure surfaces.",
    "citations": []
  },
  {
    "statement": "Habitat modifications on intertidal artificial structures altered community composition toward more natural assemblages.",
    "citations": []
  }
]

[
  {
    "statement": "The evidence shows clear differences between subtidal and intertidal zones regarding the effectiveness of adjoining cavities.",
    "citations": []
  },
  {
    "statement": "For subtidal artificial structures, studies demonstrate that both large (>100 mm) and small (≤100 mm) swimthrough habitats provide measurable benefits.",
    "citations": []
  },
  {
    "statement": "Large subtidal swimthroughs increased overall fish abundance and species richness.",
    "citations": []
  },
  {
    "statement": "Large subtidal swimthroughs supported fish species that were absent from structure surfaces without swimthroughs.",
    "citations": []
  },
  {
    "statement": "Small subtidal swimthroughs also showed positive but mixed effects.",
    "citations": []
  },
  {
    "statement": "Six fish species were present in small subtidal swimthroughs that were absent from control surfaces.",
    "citations": []
  },
  {
    "statement": "Both large and small subtidal cavity types were actively used by juvenile fish, spiny lobsters, and other marine life.",
    "citations": []
  },
  {
    "statement": "Intertidal artificial structures with swimthrough habitats show limited or no evidence of effectiveness.",
    "citations": []
  },
  {
    "statement": "No studies were found examining large (>100 mm) swimthrough habitats on intertidal structures.",
    "citations": []
  },
  {
    "statement": "Two studies on small (≤100 mm) intertidal swimthroughs found no effects on invertebrate community composition or species richness.",
    "citations": []
  },
  {
    "statement": "One study on small intertidal swimthroughs did observe increased mobile invertebrate abundance on structure surfaces.",
    "citations": []
  },
  {
    "statement": "The evidence gap and limited positive results suggest swimthrough habitats are less effective in intertidal environments compared to subtidal zones.",
    "citations": []
  }
]

[
  {
    "statement": "Creating 'rock pools' on intertidal artificial structures appears to be more effective for biodiversity enhancement compared to creating natural rocky reef topography.",
    "citations": []
  },
  {
    "statement": "Rock pools showed consistently positive results across multiple studies.",
    "citations": []
  },
  {
    "statement": "Nine out of twelve replicated controlled studies found higher species diversity and richness in pools compared to structure surfaces without pools.",
    "citations": []
  },
  {
    "statement": "Rock pools supported species that were absent from structure surfaces without pools.",
    "citations": []
  },
  {
    "statement": "Species supported by rock pools included macroalgae, mobile invertebrates, non-mobile invertebrates, and fish.",
    "citations": []
  },
  {
    "statement": "Natural rocky reef topography showed limited biodiversity benefits.",
    "citations": []
  },
  {
    "statement": "One replicated controlled study found no increase in combined macroalgae and invertebrate species richness from creating natural rocky reef topography.",
    "citations": []
  },
  {
    "statement": "The evidence for rocky reef topography was based on only two studies.",
    "citations": []
  },
  {
    "statement": "The two studies on rocky reef topography found mixed effects on species abundances.",
    "citations": []
  },
  {
    "statement": "The studies reported that limpets used shaded grooves and water-retaining depressions.",
    "citations": []
  },
  {
    "statement": "Rock pools demonstrated clear biodiversity improvements, with 18 studies examining the effects of the pools.",
    "citations": []
  },
  {
    "statement": "Rocky reef topography showed minimal measurable benefits for species richness or diversity enhancement on intertidal artificial structures.",
    "citations": []
  }
]

[
  {
    "statement": "Several interventions can be used to increase algal abundance on marine artificial structures.",
    "citations": []
  },
  {
    "statement": "Transplanting or seeding algae onto subtidal artificial structures has shown positive results.",
    "citations": [
      "3471"
    ]
  },
  {
    "statement": "The cover of canopy algae transplanted onto subtidal artificial structures increased when the algae were transplanted under cages.",
    "citations": [
      "3471"
    ]
  },
  {
    "statement": "Creating textured surfaces on subtidal artificial structures has demonstrated mixed effects on macroalgal abundance, depending on the species group and site.",
    "citations": [
      "3449"
    ]
  },
  {
    "statement": "Creating small protrusions on subtidal artificial structures has shown mixed effects on macroalgal abundance, depending on the species studied.",
    "citations": [
      "3453"
    ]
  },
  {
    "statement": "Creating groove habitats on subtidal artificial structures had mixed effects on macroalgal abundances, depending on the species group.",
    "citations": [
      "3448"
    ]
  },
  {
    "statement": "Using environmentally-sensitive materials on both intertidal and subtidal artificial structures has shown mixed effects on macroalgal abundance.",
    "citations": [
      "3469",
      "3470"
    ]
  },
  {
    "statement": "The effect of environmentally-sensitive materials on macroalgal abundance depends on the material type, species group, wave-exposure, and site.",
    "citations": [
      "3469",
      "3470"
    ]
  },
  {
    "statement": "Creating rock pools on intertidal artificial structures has demonstrated mixed effects on macroalgal abundances.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "The effect of rock pools on macroalgal abundance depends on the pool depth, shore level, species group, and site.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "Creating long flexible habitats on subtidal artificial structures supported higher combined macroalgae and invertebrate biomass compared to structure surfaces without flexible habitats.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Deeper flexible habitats on subtidal artificial structures supported higher biomass than shallower ones.",
    "citations": [
      "3451"
    ]
  },
  {
    "statement": "Transplanting organisms onto intertidal artificial structures has shown benefits for macroalgae survival.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Macroalgae transplanted onto intertidal artificial structures were more likely to survive at mid- and highshore than at lowshore.",
    "citations": [
      "3472"
    ]
  },
  {
    "statement": "Creating natural rocky reef topography on subtidal artificial structures did not increase the abundance of juvenile canopy macroalgae that settled onto the structure surfaces.",
    "citations": [
      "3446"
    ]
  },
  {
    "statement": "The abundance of juvenile canopy macroalgae on subtidal artificial structures was not increased by the creation of natural rocky reef topography, regardless of the topography's depth.",
    "citations": [
      "3446"
    ]
  }
]

[
  {
    "statement": "Creating large hole habitats (>50mm) on artificial structures shows varying biodiversity outcomes between subtidal zones in Israel and Sweden compared to intertidal zones in Australia and Europe.",
    "citations": []
  },
  {
    "statement": "Three studies examined large hole habitats in subtidal zones on an open coastline in northern Israel, in a marina in northern Israel, and off the west coast of Sweden.",
    "citations": []
  },
  {
    "statement": "All three studies on subtidal large hole habitats found that creating the habitats altered the combined macroalgae and invertebrate community composition on structures.",
    "citations": []
  },
  {
    "statement": "All three studies on subtidal large hole habitats found that creating the habitats altered the mobile invertebrate and fish community composition on structures.",
    "citations": []
  },
  {
    "statement": "Subtidal hole habitats supported species that were absent from surfaces without habitat features.",
    "citations": []
  },
  {
    "statement": "Two of three studies on subtidal large hole habitats found increased macroalgae and invertebrate species richness and/or diversity.",
    "citations": []
  },
  {
    "statement": "One study on subtidal large hole habitats found no increase in combined mobile invertebrate and fish richness.",
    "citations": []
  },
  {
    "statement": "Population responses to subtidal large hole habitats were mixed.",
    "citations": []
